export type Effort = "low" | "medium" | "high" | "xhigh";
export interface Route { model: string; effort: Effort }

export const ROUTES: Record<string, Route> = {
  readiness: { model: "claude-sonnet-5-5", effort: "low" },
  plan: { model: "claude-opus-5-5", effort: "medium" }, // the plan asks for "high" on fuzzy or cross-module tickets
  build: { model: "claude-opus-5-5", effort: "medium" }, // the default for every job not listed
  "build-hard": { model: "claude-opus-5-5", effort: "high" }, // a bug in existing code, many edge cases
  helper: { model: "claude-haiku-5-5", effort: "medium" }, // reading and search; returns file:line pointers
  qa: { model: "claude-sonnet-5-5", effort: "medium" },
  "ci-fix": { model: "claude-opus-5-5", effort: "low" }, // CI is the checker; re-run at medium if it fails
};
const LEVELS: Effort[] = ["low", "medium", "high", "xhigh"];
export const ROUTING_ENV = {
  CLAUDE_CODE_MAX_OUTPUT_TOKENS: "64000", // at 16K most long attempts were cut off
  CLAUDE_CODE_PROMPT_CACHE_TTL: "1h", // Nova waits on people; routines use 5m
};

export const routeFor = (job: string): Route => ROUTES[job] ?? ROUTES.build!;

/** A step whose checks failed is re-run once, one level higher, in the same session (warm cache). */
export const rerunOneLevelUp = async (session: NovaSession, step: Step, route: Route): Promise<Route> => {
  const higher = LEVELS[Math.min(LEVELS.indexOf(route.effort) + 1, LEVELS.length - 1)]!;
  await session.query.applyFlagSettings({ effortLevel: higher }); // from the next turn; check cache reads in the W6 spike
  await session.send(step.retryPrompt()); // streaming input: the same session, no restart
  return { model: route.model, effort: higher };
};

// No maxTurns, no maxBudgetUsd, no taskBudget: test/no-limits.test.ts fails if one appears.

import { readFileSync } from "node:fs";

// harness/package.json is one level above both src/ and dist/; its version changes on every harness release
const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")) as { version: string };
export const HARNESS_VERSION = pkg.version;
export const STEPS = ["ticket", "plan", "plan_ok", "vm", "build", "pr", "byte", "approve", "learn"] as const;
export type Step = (typeof STEPS)[number];
export interface RunTags { agent: string; jira: string; id: string }

/** Env for one Agent SDK session. Its OTel data and its gateway calls carry the same tags. */
export function stepEnv(run: RunTags, step: Step): Record<string, string> {
  if (!STEPS.includes(step)) throw new Error(`unknown step ${step}`);
  const tags = { agent: run.agent, jira: run.jira, run: run.id, step, "harness.version": HARNESS_VERSION };
  return {
    OTEL_RESOURCE_ATTRIBUTES: Object.entries(tags).map(([k, v]) => `${k}=${v}`).join(","),
    // agent, jira and run reach the gateway inside the run token; step and version ride on headers
    ANTHROPIC_CUSTOM_HEADERS: `x-ai-agents-step: ${step}\nx-ai-agents-harness: ${HARNESS_VERSION}`,
  };
}

import assert from "node:assert/strict";
import { test } from "node:test";
import type { Options } from "@anthropic-ai/claude-agent-sdk";
import { routeFor } from "../src/routing.js";

const buildOptions = (job: string): Options => ({ model: routeFor(job).model, effort: routeFor(job).effort });

test("no turn, budget or token limit is ever set", () => {
  for (const job of ["plan", "build", "qa", "unknown-job"]) {
    const options = buildOptions(job);
    assert.equal(options.maxTurns, undefined, `${job}: maxTurns must stay unset`);
    assert.equal(options.maxBudgetUsd, undefined, `${job}: maxBudgetUsd must stay unset`);
    assert.equal(options.taskBudget, undefined, `${job}: taskBudget must stay unset`);
  }
});

test("unknown jobs fall back to the build route", () => {
  assert.deepEqual(routeFor("unknown-job"), { model: "claude-opus-5-5", effort: "medium" });
});
